#!/usr/bin/env python3

# Used and synced by Canary Tests.
# Code is initially generated by AI.
"""
assert_result.py

Run a command and assert properties about its result.

Default behavior:
  - Command must FAIL (return code != 0)

Options allow asserting:
  - Exact return code
  - Success (return code == 0)
  - Required substrings in output
  - Forbidden substrings in output
  - At least one of several substrings present

Examples:

  # Expect failure containing a symbol name
  assert_result.py --contains Z3_solver_register_on_clause -- \
      python3 -c "import z3"

  # Expect success
  assert_result.py --expect-success -- \
      python3 -c "print('ok')"

  # Expect specific return code
  assert_result.py --expected-returncode 2 -- \
      some_command

All command stdout/stderr is forwarded to CI logs.
"""

import argparse
import subprocess
import sys
from typing import List


def run_command(cmd: List[str]) -> tuple[int, str]:
    proc = subprocess.run(
        cmd,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
    )
    output = proc.stdout or ""
    sys.stdout.write(output)
    sys.stdout.flush()
    return proc.returncode, output


def main() -> int:
    parser = argparse.ArgumentParser(
        description="Run a command and assert properties about its result."
    )

    parser.add_argument(
        "--expect-success",
        action="store_true",
        help="Assert that the command must succeed (return code == 0).",
    )

    parser.add_argument(
        "--expected-returncode",
        type=int,
        default=None,
        help="Assert exact return code.",
    )

    parser.add_argument(
        "--contains",
        action="append",
        default=[],
        help="Substring that must appear in output (repeatable).",
    )

    parser.add_argument(
        "--contains-any",
        action="append",
        default=[],
        help="At least one of these substrings must appear in output (repeatable).",
    )

    parser.add_argument(
        "--not-contains",
        action="append",
        default=[],
        help="Substring that must NOT appear in output (repeatable).",
    )

    parser.add_argument(
        "--label",
        default="",
        help="Optional label printed before execution.",
    )

    parser.add_argument(
        "cmd",
        nargs=argparse.REMAINDER,
        help="Command to run. Use `--` before the command.",
    )

    args = parser.parse_args()

    cmd = args.cmd
    if cmd and cmd[0] == "--":
        cmd = cmd[1:]

    if not cmd:
        print("ERROR: No command provided.", file=sys.stderr)
        return 2

    if args.label:
        print(f"\n==> {args.label}")
    print(f"$ {' '.join(cmd)}")

    code, output = run_command(cmd)

    # --- Return code checks ---
    if args.expect_success:
        if code != 0:
            print(f"ERROR: expected success (0), got {code}", file=sys.stderr)
            return 1
    elif args.expected_returncode is not None:
        if code != args.expected_returncode:
            print(
                f"ERROR: expected return code {args.expected_returncode}, got {code}",
                file=sys.stderr,
            )
            return 1
    else:
        # Default: expected failure
        if code == 0:
            print("ERROR: expected failure, but command succeeded", file=sys.stderr)
            return 1

    # --- Output checks ---
    for needle in args.contains:
        if needle not in output:
            print(f"ERROR: missing required text: {needle}", file=sys.stderr)
            return 1

    if args.contains_any:
        if not any(n in output for n in args.contains_any):
            joined = " OR ".join(args.contains_any)
            print(f"ERROR: output did not contain any of: {joined}", file=sys.stderr)
            return 1

    for needle in args.not_contains:
        if needle in output:
            print(f"ERROR: forbidden text found: {needle}", file=sys.stderr)
            return 1

    print("OK: assertion passed.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())